import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] sums = new int[51];
        sums[0] = 1;
        for (int i = 1; i <= 50; i++) {
            sums[i] = sums[i - 1] + (1 << i);
        }

        int h = sc.nextInt();
        int n = sc.nextInt();

        n += sums[h - 1];

        int[] path = new int[1000]; // assuming maximum path length
        int pathIndex = 0;
        path[pathIndex++] = n;

        while (n != 1) {
            n /= 2;
            if (pathIndex >= path.length) {
                // expand array if needed
                int[] newPath = new int[path.length * 2];
                System.arraycopy(path, 0, newPath, 0, path.length);
                path = newPath;
            }
            path[pathIndex++] = n;
        }

        int answer = 0;
        int node = 1;
        boolean flipFlag = false;

        int startIdx = 0; // index for path array
        int endIdx = pathIndex - 1; // index for path array

        // Find index of path[0] in path array
        int pathStartIndex = 0;
        for (int i = 0; i < pathIndex; i++) {
            if (path[i] == path[0]) {
                pathStartIndex = i;
                break;
            }
        }

        while (node != path[pathStartIndex]) {
            int[] tempPath = new int[h + 1];
            int tempNode = node;
            for (int i = 0; i < h; i++) {
                tempPath[i] = tempNode;
                if (!flipFlag) {
                    tempNode *= 2;
                } else {
                    tempNode = tempNode * 2 + 1;
                }
                flipFlag = !flipFlag;
            }
            if (tempNode == path[pathStartIndex]) {
                answer += h;
                break;
            }
            // Append tempNode
            int[] fullTempPath = new int[h + 2];
            System.arraycopy(tempPath, 0, fullTempPath, 0, h);
            fullTempPath[h] = tempNode;

            // Reverse tempPath
            for (int i = 0; i < h / 2; i++) {
                int tmp = fullTempPath[i];
                fullTempPath[i] = fullTempPath[h - 1 - i];
                fullTempPath[h - 1 - i] = tmp;
            }

            boolean found = false;
            for (int i = 1; i <= h; i++) {
                if (path[pathStartIndex + i] == fullTempPath[i]) {
                    answer += sums[i - 1] + h - i + 1;
                    h = i - 1;
                    node = fullTempPath[i - 1];
                    if (node == fullTempPath[i] * 2) {
                        node = fullTempPath[i] * 2 + 1;
                        flipFlag = false;
                    } else {
                        node = fullTempPath[i] * 2;
                        flipFlag = true;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                // If no match found, break to prevent infinite loop
                break;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
